---RefreshUI
---@param index number
---@param waveVo WaveVo
function UIBossDetailTabNodeMB:RefreshUI(index, waveVo)
    self.index = index

    local wave1NpcType = waveVo.wave1NpcType
    local isBoss = false
    for i, monsterType in ipairs(wave1NpcType) do
        isBoss = checkNumber(monsterType) == Constants.RoleClass.Boss
        if isBoss then break end
    end

    local text = string.format("%02d", index)
    self.BackgroundText.text = text
    self.CheckmarkText1.text = text
    self.CheckmarkText2.text = text
    self.CheckmarkText3.text = text

    KTool.SetActive(self.BackgroundBoss.gameObject, isBoss)
    KTool.SetActive(self.CheckmarkBoss.gameObject, isBoss)
end

function UIBossDetailTabNodeMB:RefreshSelectState(isSelect)
    KTool.SetActive(self.Background.gameObject, not isSelect)
    KTool.SetActive(self.Checkmark.gameObject, isSelect)
end


